/** Free dated commitments, derived from saved effective records rather than sample totals. */
public final class GoalBankActivity extends Activity {
    private final ExecutorService reader=Executors.newSingleThreadExecutor();
    private final Handler handler=new Handler(Looper.getMainLooper());
    private DatedGoalBank ledger;private Instant calculatedAt;private DatedGoalBank.Summary rangeTotal;private Map<String,DatedGoalBank.Summary> rangeParts=Map.of();
    private List<RecordEntry> records=List.of();private List<GoalCommitment> goals=List.of();
    private boolean creating,loaded,resumed,refreshing;private String selected="",failure="",actionToken,actionKind,candidateId;
    private String metric="duration",zone=ZoneId.systemDefault().getId(),motivation="";
    private RecordTrends.Range bankRange;private boolean overview;
    private int generation;private String saveFailure="";private Dialog settingsDialog,stopDialog;private RecordCalendar calendar;private Bundle restoredSettings,restoredCalendar;
    private int targetDuration=480,targetBedtime=1350,length=14,cutoff;
    private LocalDate start=LocalDate.now(),stopDay;private EditText motivationField;private Button primary;
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);if(getIntent().hasExtra("goalRangeStart")&&getIntent().hasExtra("goalRangeEnd")){try{bankRange=new RecordTrends.Range(LocalDate.parse(getIntent().getStringExtra("goalRangeStart")),LocalDate.parse(getIntent().getStringExtra("goalRangeEnd")));overview=true;}catch(java.time.DateTimeException ignored){}}selected=getIntent().getStringExtra("goal")==null?"":getIntent().getStringExtra("goal");SleepPlan plan=SleepPlans.load(this);targetDuration=plan.goal;targetBedtime=plan.bedtime;cutoff=Math.max(0,Math.min(1439,Prefs.number(this,"statsCutoff",0)));if(state!=null){overview=state.getBoolean("overview",overview);saveFailure=state.getString("saveFailure","");restoredSettings=state.getBundle("settingsDialog");restoredCalendar=state.getBundle("goalCalendar");creating=state.getBoolean("creating");selected=state.getString("selected","");metric=state.getString("metric","duration");zone=state.getString("zone",zone);motivation=state.getString("motivation","");targetDuration=state.getInt("duration",targetDuration);targetBedtime=state.getInt("bedtime",targetBedtime);length=state.getInt("length",14);cutoff=state.getInt("cutoff",cutoff);start=LocalDate.parse(state.getString("start",start.toString()));candidateId=state.getString("candidate");actionToken=state.getString("actionToken");actionKind=state.getString("actionKind");String stop=state.getString("stopDay");if(stop!=null)stopDay=LocalDate.parse(stop);}render();}
    @Override protected void onResume(){super.onResume();resumed=true;load();observe();}
    @Override protected void onPause(){resumed=false;handler.removeCallbacks(poll);rememberMotivation();super.onPause();}
    private void load(){refreshing=true;if(loaded)render();int request=++generation;Records.Factory factory=Records.factory;SleepPlans.Repository repository=SleepPlans.repository(this);reader.execute(()->{try(Store store=factory.open(getApplicationContext())){List<RecordEntry> rows=Records.all(store);List<GoalCommitment> saved=repository.goals();Instant now=Instant.now();DatedGoalBank calculated=new DatedGoalBank(saved,rows,now);GoalCommitment preferred=calculated.preferred(now);DatedGoalBank.Summary total=bankRange==null?null:calculated.summary(bankRange);Map<String,DatedGoalBank.Summary> parts=new HashMap<>();if(bankRange!=null)for(GoalCommitment g:saved)parts.put(g.id,calculated.slice(g.id,bankRange));runOnUiThread(()->{if(isDestroyed()||request!=generation)return;refreshing=false;ledger=calculated;calculatedAt=now;rangeTotal=total;rangeParts=Collections.unmodifiableMap(parts);records=rows;goals=saved;loaded=true;failure="";if(!creating&&selected.isEmpty()&&!goals.isEmpty()){selected=preferred==null?goals.get(goals.size()-1).id:preferred.id;}render();restoreControls();});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed()&&request==generation){refreshing=false;failure="Goals could not be read. "+e.getMessage();render();}});}});}
    private String date(LocalDate date){return date.format(DateTimeFormatter.ofPattern("d MMM uuuu",Locale.getDefault()));}
    private void render(){rememberMotivation();LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,creating?"Set a goal":"Goal bank",this::back);if(!failure.isEmpty()){Design.space(body,14);Design.text(body,failure,14,400,Design.MUTED);Design.button(body,"Try again",true,this::load);return;}if(!loaded){Design.space(body,20);Design.text(body,"Loading goals…",15,400,Design.MUTED);return;}if(refreshing){Design.text(body,"Updating saved progress…",12,400,Design.MUTED);}if(creating){create(body);return;}if(overview&&bankRange!=null){rangeOverview(body);return;}
        if(goals.isEmpty()){Design.space(body,34);Design.text(body,"Build a sleep habit",25,700,Design.INK);Design.space(body,12);Design.text(body,"Choose a bedtime or duration target for 14 or 30 days. Every goal is free.",15,400,Design.MUTED);Design.space(body,20);Design.text(body,"Surplus and shortfall balance across recorded days. Missing days stay unknown.",13,400,Design.MUTED);LinearLayout footer=RecordUi.footer(body);primary=Design.button(footer,"Set your first goal",true,this::begin);return;}
        HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);LinearLayout choices=Design.row(this);for(GoalCommitment goal:goals){String name=(goal.metric.equals("duration")?"Duration":"Bedtime")+" · "+goal.start.format(DateTimeFormatter.ofPattern("d MMM",Locale.getDefault()));choices.addView(RecordUi.chip(this,name,goal.id.equals(selected),()->{selected=goal.id;render();}),new LinearLayout.LayoutParams(-2,Design.dp(this,48)));}scroll.addView(choices);body.addView(scroll);
        GoalCommitment current=goals.stream().filter(g->g.id.equals(selected)).findFirst().orElse(goals.get(goals.size()-1));selected=current.id;GoalProgress progress=ledger.progress.get(current.id);Design.space(body,12);Design.text(body,current.metric.equals("duration")?"Duration goal":"Bedtime goal",15,600,Design.INK);Design.space(body,5);Design.text(body,(current.metric.equals("duration")?PlanActivity.duration(current.target):PlanActivity.clock(this,current.target))+" · "+date(current.start)+" – "+date(current.end()),13,400,Design.MUTED);Design.space(body,12);
        TextView balance=Design.text(body,progress.observed==0?"—":GoalProgress.signed(progress.balance),43,700,Design.INK);balance.setText(RecordUi.units(balance.getText().toString()));Design.space(body,6);Design.text(body,progress.observed==0?"No closed recorded days yet":progress.balance<0?"Below target on recorded days":progress.balance>0?"Ahead on recorded days":"On target on recorded days",15,600,Design.INK);Design.space(body,8);
        String status=SleepDay.label(calculatedAt.toEpochMilli(),ZoneId.of(current.zone),current.cutoff).isBefore(current.start)?"Starts "+date(current.start):current.stopped!=null?"Stopped · progress kept":progress.complete?progress.balance>=0?"Period complete · target met":"Period complete · target missed":progress.ended?"Period ended · incomplete record coverage":"In progress · "+progress.days.size()+" of "+current.days+" days closed";
        Design.text(body,status,12,500,Design.BROWN);Design.space(body,6);Design.text(body,progress.observed+" recorded · "+progress.unknown+" unrecorded closed days",12,400,Design.MUTED);if(!current.motivation.isEmpty()){Design.space(body,10);Design.text(body,current.motivation,14,500,Design.INK);}
        RecordUi.heading(body,"Daily surplus & shortfall");body.addView(new GoalChart(this,current,progress,false),new LinearLayout.LayoutParams(-1,Design.dp(this,170)));RecordUi.heading(body,"Goal bank over time");body.addView(new GoalChart(this,current,progress,true),new LinearLayout.LayoutParams(-1,Design.dp(this,145)));Design.space(body,8);PlanActivity.detail(body,"info","How this bank is counted",null,null,()->settingsDialog=SleepPicker.message(this,"Recorded progress","Only closed sleep days count. Current, future and missing days stay blank. "+current.zone+" · day starts "+PlanActivity.clock(this,current.cutoff)+". "+(current.metric.equals("duration")?"Recorded and manual durations merge, including naps. Overlapping minutes count once; unmarked awake time may be included.":"Bedtime uses the longest non-nap period of at least 3 h; it is not measured sleep onset.")));
        if(!saveFailure.isEmpty()){Design.text(body,saveFailure,13,500,Design.BROWN);Design.space(body,8);}if(current.stopped==null&&!progress.ended)RecordUi.quietButton(body,"Stop this goal",()->confirmStop(current));RecordUi.quietButton(body,"View sleep history",()->startActivity(RecordUi.intent(this,HistoryActivity.class)));LinearLayout footer=RecordUi.footer(body);primary=Design.button(footer,actionToken==null?"New goal":"Saving…",true,this::begin);primary.setEnabled(actionToken==null);if(actionToken!=null)RecordUi.enabled(body,false);if(actionToken!=null&&resumed)observe();
    }
    private void rangeOverview(LinearLayout body){
        DatedGoalBank.Summary total=rangeTotal;Design.space(body,16);Design.text(body,date(bankRange.start)+" – "+date(bankRange.end),13,400,Design.MUTED);Design.space(body,12);TextView amount=Design.text(body,total.observed==0?"—":GoalProgress.signed(total.balance),48,700,Design.INK);amount.setText(RecordUi.units(amount.getText().toString()));Design.space(body,6);Design.text(body,"Recorded goal balance",17,600,Design.INK);Design.space(body,8);Design.text(body,total.hasDates()?total.observed+" recorded · "+total.unknown+" missing closed days":"No dated duration goal in this range",13,400,Design.MUTED);
        for(GoalCommitment goal:goals){if(!goal.metric.equals("duration"))continue;DatedGoalBank.Summary part=rangeParts.get(goal.id);if(!part.hasDates())continue;Design.space(body,12);PlanActivity.detail(body,"report",PlanActivity.duration(goal.target)+" duration goal",date(goal.start)+" – "+date(goal.through()),part.observed==0?"No days yet":GoalProgress.signed(part.balance),()->{selected=goal.id;overview=false;render();});Design.line(body);}
        Design.space(body,14);PlanActivity.detail(body,"info","How this bank is counted",null,null,()->settingsDialog=SleepPicker.message(this,"Recorded progress","Each period keeps its saved duration target, time zone and day boundary. Only closed recorded days count; missing and uncommitted dates create no shortfall. Overlapping minutes count once."));LinearLayout footer=RecordUi.footer(body);primary=Design.button(footer,"New goal",true,this::begin);
    }
    private void begin(){if(actionToken!=null)return;overview=false;saveFailure="";SleepPlan p=SleepPlans.load(this);targetDuration=p.goal;targetBedtime=p.bedtime;zone=ZoneId.systemDefault().getId();cutoff=Math.max(0,Math.min(1439,Prefs.number(this,"statsCutoff",0)));start=SleepDay.label(System.currentTimeMillis(),ZoneId.of(zone),cutoff);metric="duration";length=14;motivation="";candidateId=UUID.randomUUID().toString();motivationField=null;creating=true;render();}
    private void create(LinearLayout body){Design.space(body,12);RecordUi.segments(body,new String[]{"Sleep duration","Bedtime"},metric.equals("duration")?0:1,index->{metric=index==0?"duration":"bedtime";render();});Design.space(body,20);TextView target=Design.text(body,metric.equals("duration")?PlanActivity.duration(targetDuration):PlanActivity.clock(this,targetBedtime),48,700,Design.INK);target.setGravity(Gravity.CENTER);target.setContentDescription("Choose goal target");target.setMinHeight(Design.dp(this,64));target.setOnClickListener(v->chooseTarget());target.setText(RecordUi.units(target.getText().toString()));Design.space(body,8);LinearLayout adjust=Design.row(this);Button minus=RecordUi.quietButton(Design.col(this),"−  Earlier / less",()->change(-15)),plus=RecordUi.quietButton(Design.col(this),"+  Later / more",()->change(15));((android.view.ViewGroup)minus.getParent()).removeView(minus);((android.view.ViewGroup)plus.getParent()).removeView(plus);adjust.addView(minus,new LinearLayout.LayoutParams(0,Design.dp(this,48),1));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(0,Design.dp(this,48),1);pp.leftMargin=Design.dp(this,8);adjust.addView(plus,pp);body.addView(adjust);Design.space(body,16);RecordUi.segments(body,new String[]{"14 days","30 days"},length==14?0:1,index->{length=index==0?14:30;render();});
        PlanActivity.detail(body,"calendar","Starts",null,date(start),this::chooseStart);Design.line(body);PlanActivity.detail(body,"calendar","Ends","The target stays fixed for this period",date(start.plusDays(length-1)),null);RecordUi.heading(body,"Why this goal matters");motivationField=new EditText(this);motivationField.setText(motivation);motivationField.setHint("Optional motivation");motivationField.setContentDescription("Goal motivation");motivationField.setTextSize(14*Appearance.scale(this));motivationField.setTextColor(Design.INK);motivationField.setTypeface(Design.font(this,400));motivationField.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);motivationField.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(240)});motivationField.setBackground(Design.shape(this,Design.SOFT,12));Design.pad(motivationField,12,12);body.addView(motivationField,new LinearLayout.LayoutParams(-1,-2));Design.space(body,14);Design.text(body,"Free · no payment or wager",14,600,Design.INK);Design.space(body,8);Design.text(body,"Uses "+zone+" and a day boundary of "+PlanActivity.clock(this,cutoff)+". Missing days never become invented sleep.",12,400,Design.MUTED);Design.space(body,8);Design.text(body,"Goals and plans stay on this phone. Current JSON backups exclude these settings.",11,400,Design.MUTED);LinearLayout footer=RecordUi.footer(body);if(!saveFailure.isEmpty()){Design.text(footer,saveFailure,13,500,Design.BROWN);Design.space(footer,8);}primary=Design.button(footer,actionToken==null?"Start goal":"Saving…",true,this::startGoal);primary.setEnabled(actionToken==null);if(actionToken!=null)RecordUi.enabled(body,false);if(actionToken!=null&&resumed)observe();}
    private void rememberMotivation(){if(motivationField!=null&&creating)motivation=motivationField.getText().toString();}
    private void change(int amount){if(actionToken!=null)return;if(metric.equals("duration"))targetDuration=Math.max(20,Math.min(810,targetDuration+amount));else targetBedtime=Math.floorMod(targetBedtime+amount,1440);render();}
    private void chooseTarget(){if(actionToken!=null)return;if(settingsDialog!=null&&settingsDialog.isShowing())return;settingsDialog=metric.equals("duration")?SleepPicker.duration(this,"Goal duration",targetDuration,20,810,value->{targetDuration=value;render();}):SleepPicker.time(this,"Goal bedtime",targetBedtime,value->{targetBedtime=value;render();});}
    private void chooseStart(){if(actionToken!=null||calendar!=null&&calendar.showing())return;calendar=new RecordCalendar(this,"Goal starts",start,restoredCalendar,value->{start=value;render();},null);restoredCalendar=null;}
    private void restoreControls(){if(!creating)return;if(restoredCalendar!=null)chooseStart();if(restoredSettings!=null){Bundle saved=restoredSettings;restoredSettings=null;chooseTarget();if(settingsDialog!=null)settingsDialog.onRestoreInstanceState(saved);}}
    private GoalCommitment candidate(){rememberMotivation();return new GoalCommitment(candidateId,metric,metric.equals("duration")?targetDuration:targetBedtime,start,length,zone,cutoff,motivation,null);}
    private void startGoal(){if(actionToken!=null)return;try{candidate();saveFailure="";actionKind="create";actionToken=UUID.randomUUID().toString();render();}catch(Exception e){saveFailure=e.getMessage();render();}}
    private void confirmStop(GoalCommitment goal){if(actionToken!=null)return;LocalDate current=SleepDay.label(System.currentTimeMillis(),ZoneId.of(goal.zone),goal.cutoff);LocalDate through=current.minusDays(1);Dialog dialog=new Dialog(this);stopDialog=dialog;dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout content=Design.col(this);Design.pad(content,22,22);content.setBackground(Design.shape(this,Design.CREAM,24));Design.text(content,"Stop this goal?",22,600,Design.INK);Design.space(content,16);Design.text(content,"Keep progress through the latest closed sleep day. Past targets and records stay available.",14,400,Design.MUTED);Design.button(content,"Stop goal",true,()->{dialog.dismiss();selected=goal.id;stopDay=through;actionKind="stop";actionToken=UUID.randomUUID().toString();saveFailure="";render();});Design.button(content,"Keep going",false,dialog::dismiss);dialog.setContentView(content);dialog.show();dialog.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));dialog.getWindow().setLayout(getResources().getDisplayMetrics().widthPixels-Design.dp(this,32),-2);}
    private void observe(){if(!resumed||actionToken==null)return;GoalCommitment draft=actionKind.equals("create")?candidate():null;String id=selected;LocalDate through=stopDay;SleepPlans.Repository repository=SleepPlans.repository(this);PlanOperations.Operation operation=PlanOperations.start(this,actionToken,app->{if(draft!=null)repository.add(draft);else repository.stop(id,through);return null;});if(!operation.done){handler.removeCallbacks(poll);handler.postDelayed(poll,100);return;}PlanOperations.forget(actionToken);actionToken=null;if(operation.error!=null){saveFailure=operation.error;render();return;}saveFailure="";if(draft!=null)selected=draft.id;creating=false;motivationField=null;load();}
    private final Runnable poll=this::observe;
    private void back(){if(actionToken!=null){Ui.toast(this,"Please wait for this save to finish.");return;}if(creating){creating=false;motivationField=null;saveFailure="";render();}else if(bankRange!=null&&!overview){overview=true;render();}else finish();}
    @Override public void finish(){if(actionToken!=null){Ui.toast(this,"Please wait for this save to finish.");return;}if(isTaskRoot())startActivity(RecordUi.intent(this,MainActivity.class));super.finish();}
    // Android 11/12 fallback; newer releases use the platform callback.
    @android.annotation.SuppressLint("GestureBackNavigation")
    @Override public void onBackPressed(){back();}
    @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);rememberMotivation();state.putBoolean("overview",overview);state.putString("saveFailure",saveFailure);if(settingsDialog instanceof SleepPicker.StateDialog&&settingsDialog.isShowing())state.putBundle("settingsDialog",settingsDialog.onSaveInstanceState());if(calendar!=null&&calendar.showing())state.putBundle("goalCalendar",calendar.state());state.putBoolean("creating",creating);state.putString("selected",selected);state.putString("metric",metric);state.putString("zone",zone);state.putString("motivation",motivation);state.putInt("duration",targetDuration);state.putInt("bedtime",targetBedtime);state.putInt("length",length);state.putInt("cutoff",cutoff);state.putString("start",start.toString());state.putString("candidate",candidateId);state.putString("actionToken",actionToken);state.putString("actionKind",actionKind);if(stopDay!=null)state.putString("stopDay",stopDay.toString());}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus){RecordUi.lightBars(this);if(loaded)restoreControls();}}
    void awaitReaders(long timeoutMs) throws Exception {if(reader.isShutdown()){if(!reader.awaitTermination(timeoutMs,TimeUnit.MILLISECONDS))throw new java.util.concurrent.TimeoutException("Goal readers still active");}else reader.submit(()->{}).get(timeoutMs,TimeUnit.MILLISECONDS);}
    @Override protected void onDestroy(){handler.removeCallbacks(poll);generation++;if(calendar!=null)calendar.close();if(settingsDialog!=null)settingsDialog.dismiss();if(stopDialog!=null)stopDialog.dismiss();reader.shutdown();super.onDestroy();}
}
